/* @autogenerated */
import { NavigationCancel, NavigationEnd, NavigationStart, ResolveEnd, ResolveStart, Router } from '@angular/router';
import { of, Subject } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { AuthorizationAccessService } from './authorization-access.service';

const KEY = 'last-non-oidc-route';

describe('AuthorizationAccessService', () => {
  let events$: Subject<any>;
  let router: Router;
  const state = { language$: of('es'), tenant$: of('main') } as unknown as AppStateService;

  beforeEach(() => {
    sessionStorage.clear();
    localStorage.removeItem(KEY);
    events$ = new Subject<any>();
    router = {
      events: events$,
      navigateByUrl: jasmine.createSpy('navigateByUrl'),
      navigate: jasmine.createSpy('navigate'),
    } as unknown as Router;
  });

  it('stores last non auth route on NavigationEnd only', () => {
    new AuthorizationAccessService(router, state);

    events$.next(new NavigationStart(1, '/start'));
    events$.next(new ResolveStart(1, '/start', '/start', {} as any));
    events$.next(new ResolveEnd(1, '/start', '/start', {} as any));
    events$.next(new NavigationCancel(1, '/start', 'guard rejected'));
    expect(sessionStorage.getItem(KEY)).toBeNull();

    events$.next(new NavigationEnd(1, '/home', '/home'));
    expect(sessionStorage.getItem(KEY)).toBe('/home');

    events$.next(new NavigationEnd(2, '/login-redirect', '/login-redirect'));
    expect(sessionStorage.getItem(KEY)).toBe('/home');
  });

  it('writes once per navigation and only to sessionStorage', () => {
    spyOn(Storage.prototype, 'setItem').and.callThrough();
    new AuthorizationAccessService(router, state);

    events$.next(new NavigationStart(1, '/home'));
    events$.next(new ResolveStart(1, '/home', '/home', {} as any));
    events$.next(new ResolveEnd(1, '/home', '/home', {} as any));
    events$.next(new NavigationEnd(1, '/home', '/home'));

    expect(Storage.prototype.setItem).toHaveBeenCalledTimes(1);
    expect(localStorage.getItem(KEY)).toBeNull();
  });

  it('remember ignores auth routes', () => {
    const service = new AuthorizationAccessService(router, state);

    service.remember('/unauthorized?reason=401');
    expect(sessionStorage.getItem(KEY)).toBeNull();

    service.remember('/es/main/tenant');
    expect(sessionStorage.getItem(KEY)).toBe('/es/main/tenant');
  });

  it('loads last route or current language and tenant', () => {
    const service = new AuthorizationAccessService(router, state);

    sessionStorage.setItem(KEY, '/last');
    service.loadLastRoute();
    expect(router.navigateByUrl).toHaveBeenCalledWith('/last');

    sessionStorage.removeItem(KEY);
    service.loadLastRoute();
    expect(router.navigate).toHaveBeenCalledWith(['es', 'main']);
  });

  it('clear removes the stored route', () => {
    const service = new AuthorizationAccessService(router, state);

    sessionStorage.setItem(KEY, '/some-route');
    service.clear();

    expect(sessionStorage.getItem(KEY)).toBeNull();
  });

  it('clear is a no-op when nothing is stored', () => {
    const service = new AuthorizationAccessService(router, state);

    expect(() => service.clear()).not.toThrow();
    expect(sessionStorage.getItem(KEY)).toBeNull();
  });
});
